# Construct the transformed grid
grid = []
for r in range(12):
    row = []
    for c in range(12):
        if r < 3 and c < 4:
            # Keep original pattern
            val = 1 if (r + c) % 2 == 0 else 2
        elif 8 <= r <= 10 and 1 <= c <= 4:
            # Replace zeros with same pattern (maintaining alignment at position (8,1))
            val = 1 if ((r - 8) + (c - 1)) % 2 == 0 else 2
        else:
            val = 8
        row.append(val)
    grid.append(row)

print('{"action": "submit", "grid": ' + str(grid))
